#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

const ll MOD = 1000000007;
const ll INV2 = 500000004;

ll mod128(i128 x) {
    x %= MOD;
    if (x < 0) x += MOD;
    return static_cast<ll>(x);
}

ll modPow(ll base, i128 exp) {
    ll result = 1;
    base %= MOD;
    if (base < 0) base += MOD;

    while (exp > 0) {
        if (exp & 1)
            result = static_cast<ll>((i128)result * base % MOD);
        base = static_cast<ll>((i128)base * base % MOD);
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, m, l, r;
    cin >> n >> m >> l >> r;

    i128 count = (i128)r - l + 1;
    i128 even = count / 2;
    if ((count & 1) && l % 2 == 0)
        ++even;
    i128 odd = count - even;

    i128 cells = (i128)n * m;
    ll total = mod128(count);
    ll difference = mod128(even - odd);

    ll answer = (modPow(total, cells) + modPow(difference, cells)) % MOD;
    answer = static_cast<ll>((i128)answer * INV2 % MOD);

    cout << answer << '\n';
    return 0;
}

